package fraymus.workspace;
import org.json.*;

final class MetricReport {
    static JSONObject build(JSONObject view){String json=view.toString().replace("<","\\u003c");String html="""
        <!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Measured plane037</title>
        <style>body{background:#101b26;color:#edf4fa;font:16px system-ui;margin:0;padding:24px;max-width:1100px}p{line-height:1.6;color:#bed0df}select,button{font:inherit;background:#243c50;color:white;padding:8px}canvas{width:100%;background:#152739;border-radius:12px;margin:14px 0}table{border-collapse:collapse;width:100%}td,th{border-bottom:1px solid #375169;padding:8px;text-align:left;white-space:nowrap}.scroll{overflow:auto}pre{white-space:pre-wrap;overflow-wrap:anywhere}</style>
        <h1>Real-world plane · scale, time & uncertainty</h1><p id="identity"></p><p id="meaning"></p><label>Metric <select id="metric"><option value="x">X / metres</option><option value="y">Y / metres</option><option value="radius">Uncertainty radius / metres</option><option value="speed">Displacement speed / m/s</option></select></label><canvas id="chart" width="1000" height="310"></canvas><p>Teal: actual derived samples. X/Y show ±radius bounds. Radius is an empirical or assumed bound, not a guarantee. All missing/unprojectable results remain in the table. Speed uses differences of filtered positions; it is not independently calibrated velocity confidence.</p><div class="scroll"><table><thead><tr><th>Seconds</th><th>Frame</th><th>Body</th><th>Status</th><th>X m</th><th>Y m</th><th>Radius m</th><th>Speed m/s</th></tr></thead><tbody id="rows"></tbody></table></div><details><summary>Measurement provenance</summary><pre id="provenance"></pre></details>
        <script id="evidence" type="application/json">__JSON__</script><script>
        const d=JSON.parse(document.getElementById('evidence').textContent),$=id=>document.getElementById(id);window.metricEvidence=d;$('identity').textContent='World '+d.nativeBinding.worldId+' · native revision '+d.nativeBinding.expectedRevision+' · observation '+d.runId+(d.nativeStale?' · STALE native binding':'');$('meaning').textContent=d.scope+' '+d.uncertaintyMeaning;$('provenance').textContent=JSON.stringify({geometry:d.geometry,clock:d.clock,profile:d.profile,traceSha256:d.runTraceSha256},null,2);
        for(const r of d.rows){const tr=document.createElement('tr');for(const v of [r.seconds.toFixed(3),r.sourceFrame,r.bodyId,r.status,r.positionM?.[0]?.toFixed(4)??'absent',r.positionM?.[1]?.toFixed(4)??'absent',r.radiusM?.toFixed(4)??'absent',r.speedMps?.toFixed(4)??'absent']){const td=document.createElement('td');td.textContent=v;tr.append(td);}$('rows').append(tr);}
        function draw(){const mode=$('metric').value,series=[];for(const body of [...new Set(d.rows.map(r=>r.bodyId))]){const rows=d.rows.filter(r=>r.bodyId===body&&r.positionM),get=r=>mode==='x'?r.positionM[0]:mode==='y'?r.positionM[1]:mode==='radius'?r.radiusM:r.speedMps;series.push({body,points:rows.filter(r=>Number.isFinite(get(r))).map(r=>[r.seconds,get(r)])});if(mode==='x'||mode==='y')for(const sign of [-1,1])series.push({body,bound:sign,points:rows.map(r=>[r.seconds,get(r)+sign*r.radiusM])});}window.metricChart={mode,series};$('chart').dataset.proof=JSON.stringify({mode,series});const c=$('chart'),ctx=c.getContext('2d'),all=series.flatMap(s=>s.points);ctx.clearRect(0,0,c.width,c.height);if(!all.length)return;let xs=all.map(p=>p[0]),ys=all.map(p=>p[1]),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys);for(const s of series){ctx.strokeStyle=s.bound?'#657d9b':'#6fe2bd';ctx.beginPath();s.points.forEach((p,i)=>{let x=50+920*(p[0]-xmin)/Math.max(.001,xmax-xmin),y=265-240*(p[1]-ymin)/Math.max(.001,ymax-ymin);if(i)ctx.lineTo(x,y);else ctx.moveTo(x,y);});ctx.stroke();}ctx.fillStyle='#dfecf7';ctx.font='13px system-ui';ctx.fillText(ymax.toFixed(3),2,20);ctx.fillText(ymin.toFixed(3),2,270);ctx.fillText('seconds '+xmin.toFixed(2)+' → '+xmax.toFixed(2),50,300);}$('metric').onchange=draw;draw();
        </script></html>
        """.replace("__JSON__",json);return new JSONObject().put("title","Measured plane · "+view.getString("runId").substring(0,8)).put("files",new JSONObject().put("index.html",html).put("metric-data.json",view.toString())).put("sources",new JSONArray().put(new JSONObject().put("runId",view.getString("runId")).put("worldId",view.getJSONObject("nativeBinding").getString("worldId")).put("traceSha256",view.getString("runTraceSha256"))));}
}
